From ef29da91f65a3dbb11dbfc4dbd1dbf3417c2d05d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:32:55 +0100
Subject: [PATCH] libtaskmanager: Recompute window screens when screens come
 and go

The screen of each window was refreshed when a screen changed geometry
but not when one was added or removed, so after re-docking a window kept
its old screen and was listed in the task manager of the wrong screen.

BUG: 520961
---
 libtaskmanager/abstractwindowtasksmodel.cpp | 28 +++++++++++++--------
 1 file changed, 18 insertions(+), 10 deletions(-)

diff --git a/libtaskmanager/abstractwindowtasksmodel.cpp b/libtaskmanager/abstractwindowtasksmodel.cpp
index 90af2071e4..13c2a382be 100644
--- a/libtaskmanager/abstractwindowtasksmodel.cpp
+++ b/libtaskmanager/abstractwindowtasksmodel.cpp
@@ -15,28 +15,36 @@ AbstractWindowTasksModel::AbstractWindowTasksModel(QObject *parent)
     : AbstractTasksModel(parent)
 {
     // TODO: The following will refresh the ScreenGeometry data role for
-    // all rows whenever any screen is added or changes its geometry. No
-    // attempt is made to be intelligent and exempt rows that are tech-
+    // all rows whenever any screen is added, removed or changes its geometry.
+    // No attempt is made to be intelligent and exempt rows that are tech-
     // nically unaffected by the change. Doing so would require tracking
     // far more state (i.e. what screen a window is on) and be so
     // complicated as to invite bugs. As the trigger conditions are
     // expected to be rare, this would be premature optimization at this
     // time. That assessment may change in the future.

-    auto screenAdded = [this](const QScreen *screen) {
-        connect(screen, &QScreen::geometryChanged, this, [this]() {
-            if (rowCount() == 0) {
-                return;
-            }
-            Q_EMIT dataChanged(index(0, 0), index(rowCount() - 1, 0), QList<int>{ScreenGeometry});
-        });
+    auto screensChanged = [this]() {
+        if (rowCount() == 0) {
+            return;
+        }
+        Q_EMIT dataChanged(index(0, 0), index(rowCount() - 1, 0), QList<int>{ScreenGeometry});
     };

-    connect(qGuiApp, &QGuiApplication::screenAdded, this, screenAdded);
+    auto screenAdded = [this, screensChanged](const QScreen *screen) {
+        connect(screen, &QScreen::geometryChanged, this, screensChanged);
+    };

     for (const auto screens = QGuiApplication::screens(); const QScreen *screen : screens) {
         screenAdded(screen);
     }
+
+    // A window that was placed before its screen appeared (or after it went away) gets a new screen too
+    connect(qGuiApp, &QGuiApplication::screenAdded, this, [screenAdded, screensChanged](const QScreen *screen) {
+        screenAdded(screen);
+        screensChanged();
+    });
+    // Queued, so the removed screen is gone from QGuiApplication::screens() by then
+    connect(qGuiApp, &QGuiApplication::screenRemoved, this, screensChanged, Qt::QueuedConnection);
 }

 AbstractWindowTasksModel::~AbstractWindowTasksModel() = default;
